def test_field_roundtrip(regs):
    regs.TPROC_CTRL_REG.CTRL.write(0xffff)
    assert regs.TPROC_CTRL_REG.CTRL.read() == 0xffff
    regs.TPROC_CTRL_REG.CTRL.write(0)
    regs.TPROC_CFG_REG.CFG.write(0xffff)
    assert regs.TPROC_CFG_REG.CFG.read() == 0xffff
    regs.TPROC_CFG_REG.CFG.write(0)
    regs.MEM_ADDR_REG.ADDR.write(0xffff)
    assert regs.MEM_ADDR_REG.ADDR.read() == 0xffff
    regs.MEM_ADDR_REG.ADDR.write(0)
    regs.MEM_LEN_REG.LEN.write(0xffff)
    assert regs.MEM_LEN_REG.LEN.read() == 0xffff
    regs.MEM_LEN_REG.LEN.write(0)
    regs.MEM_DT_I_REG.DT.write(0xdeadbeef)
    assert regs.MEM_DT_I_REG.DT.read() == 0xdeadbeef
    regs.MEM_DT_I_REG.DT.write(0)
    regs.TPROC_W_DT1_REG.DT.write(0xdeadbeef)
    assert regs.TPROC_W_DT1_REG.DT.read() == 0xdeadbeef
    regs.TPROC_W_DT1_REG.DT.write(0)
    regs.TPROC_W_DT2_REG.DT.write(0xdeadbeef)
    assert regs.TPROC_W_DT2_REG.DT.read() == 0xdeadbeef
    regs.TPROC_W_DT2_REG.DT.write(0)
    regs.CORE_CFG_REG.CFG.write(0xff)
    assert regs.CORE_CFG_REG.CFG.read() == 0xff
    regs.CORE_CFG_REG.CFG.write(0)
    regs.READ_SEL_REG.SEL.write(0xff)
    assert regs.READ_SEL_REG.SEL.read() == 0xff
    regs.READ_SEL_REG.SEL.write(0)


def test_register_independence(regs):
    regs.TPROC_CTRL_REG.CTRL.write(0xffff)
    regs.TPROC_CFG_REG.CFG.write(0xffff)
    regs.MEM_ADDR_REG.ADDR.write(0xffff)
    regs.MEM_LEN_REG.LEN.write(0xffff)
    regs.MEM_DT_I_REG.DT.write(0xabcd)
    regs.TPROC_W_DT1_REG.DT.write(0xabcd)
    regs.TPROC_W_DT2_REG.DT.write(0xabcd)
    regs.CORE_CFG_REG.CFG.write(0xff)
    regs.READ_SEL_REG.SEL.write(0xff)
    assert regs.TPROC_CTRL_REG.CTRL.read() == 0xffff
    assert regs.TPROC_CFG_REG.CFG.read() == 0xffff
    assert regs.MEM_ADDR_REG.ADDR.read() == 0xffff
    assert regs.MEM_LEN_REG.LEN.read() == 0xffff
    assert regs.MEM_DT_I_REG.DT.read() == 0xabcd
    assert regs.TPROC_W_DT1_REG.DT.read() == 0xabcd
    assert regs.TPROC_W_DT2_REG.DT.read() == 0xabcd
    assert regs.CORE_CFG_REG.CFG.read() == 0xff
    assert regs.READ_SEL_REG.SEL.read() == 0xff
